CREATE TABLE work_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('maintenance','turnover')),state text NOT NULL CHECK(state IN('open','completed')),blocking boolean NOT NULL DEFAULT true,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id));ALTER TABLE work_orders ENABLE ROW LEVEL SECURITY;ALTER TABLE work_orders FORCE ROW LEVEL SECURITY;CREATE POLICY work_order_read ON work_orders FOR SELECT TO kost_app USING(organization_id=current_org() AND can_access_location(organization_id,property_id));GRANT SELECT ON work_orders TO kost_app;
CREATE TABLE room_readiness_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,room_version integer NOT NULL,checklist_version integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id));ALTER TABLE room_readiness_events ENABLE ROW LEVEL SECURITY;ALTER TABLE room_readiness_events FORCE ROW LEVEL SECURITY;CREATE POLICY readiness_read ON room_readiness_events FOR SELECT TO kost_app USING(organization_id=current_org() AND can_access_location(organization_id,property_id));GRANT SELECT ON room_readiness_events TO kost_app;
CREATE OR REPLACE FUNCTION guard_room_shape() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE levels integer;today date;BEGIN IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.property_id<>OLD.property_id OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;END IF;SELECT floors,(clock_timestamp() AT TIME ZONE timezone)::date INTO levels,today FROM public.properties WHERE organization_id=NEW.organization_id AND id=NEW.property_id AND archived_at IS NULL;IF levels IS NULL OR NEW.floor>levels THEN RAISE EXCEPTION 'PROPERTY_CONFIGURATION_REQUIRED' USING ERRCODE='P0409';END IF;IF NEW.condition='ready' THEN IF TG_OP='INSERT' THEN RAISE EXCEPTION 'READINESS_WORKFLOW_REQUIRED' USING ERRCODE='P0409';END IF;IF OLD.condition<>'inspection' OR coalesce(length(trim(current_setting('app.ready_reason',true))),0)<3 OR NOT public.can_manage_inventory(NEW.organization_id,NEW.property_id) OR NOT EXISTS(SELECT FROM public.users WHERE id=public.current_actor() AND verified_at IS NOT NULL) THEN RAISE EXCEPTION 'READINESS_WORKFLOW_REQUIRED' USING ERRCODE='P0409';END IF;IF NOT EXISTS(SELECT FROM public.room_checklists c WHERE c.room_id=NEW.id AND c.water AND c.electric AND c.lock AND c.furniture AND c.clean AND c.recorded_at IS NOT NULL) OR EXISTS(SELECT FROM public.room_presence WHERE room_id=NEW.id) OR EXISTS(SELECT FROM public.leases WHERE room_id=NEW.id) OR EXISTS(SELECT FROM public.work_orders WHERE room_id=NEW.id AND state='open' AND blocking) OR EXISTS(SELECT FROM public.room_allocations WHERE room_id=NEW.id AND kind='block' AND state='active' AND daterange(starts_on,ends_on,'[)') @> today) THEN RAISE EXCEPTION 'ROOM_NOT_READY' USING ERRCODE='P0409';END IF;END IF;RETURN NEW;END $$;
CREATE FUNCTION mark_initial_room_ready(org uuid,rid uuid,expected integer,why text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE r public.rooms%ROWTYPE;cv integer;BEGIN SELECT * INTO r FROM public.rooms WHERE id=rid AND organization_id=org AND archived_at IS NULL;IF NOT FOUND OR NOT public.can_manage_inventory(org,r.property_id) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;IF length(trim(why)) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'VALIDATION_ERROR' USING ERRCODE='P0422';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('inventory-location:'||org::text||':'||r.property_id::text,0));SELECT * INTO r FROM public.rooms WHERE id=rid AND organization_id=org FOR UPDATE;IF r.version<>expected THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;PERFORM set_config('app.ready_reason',why,true);UPDATE public.rooms SET condition='ready',version=version+1 WHERE id=rid RETURNING version INTO expected;PERFORM set_config('app.ready_reason','',true);SELECT version INTO cv FROM public.room_checklists WHERE room_id=rid;INSERT INTO public.room_readiness_events(organization_id,property_id,room_id,room_version,checklist_version,actor_id,reason)VALUES(org,r.property_id,rid,expected,cv,public.current_actor(),why);INSERT INTO public.audit_logs(organization_id,actor_id,action,object_id,details)VALUES(org,public.current_actor(),'room.initial_ready',rid,jsonb_build_object('version',expected,'checklistVersion',cv,'reason',why));RETURN expected;END $$;REVOKE ALL ON FUNCTION mark_initial_room_ready(uuid,uuid,integer,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION mark_initial_room_ready(uuid,uuid,integer,text) TO kost_app;
